    if (rows2) rows2.innerHTML = shown5.length ? shown5.map(rowHtml2).join("") : `<div class="vacio">${t("accountsMore.nearby.none", { professionals: term("medico", { number: "p" }) })}</div>`;
    pages?.classList.remove("hide");
